urlset:
{% set SITEURL = SITEURL_ORG %}
  {% for page in pages if page.lang == DEFAULT_LANG %}
    {% if page.url %}
      {% set canonical_url = SITEURL ~ '/' ~ page.url %}
    {% else %}
      {% set canonical_url = SITEURL ~ '/' %}
    {% endif %}


      {{ canonical_url }}

    {% set last_date = page.modified or page.date or None %}
    {% if last_date %}
      {{ last_date.strftime('%Y-%m-%d') }}
    {% endif %}

      {# Frekvence a priorita – můžete nechat pevně nebo číst z metadat #}
      monthly
      0.7

      {% for trans in page.translations %}
        {# Sestavíme absolutní URL překladu #}
        {% if trans.url %}
          {% set trans_url = SITEURL ~ '/' ~ trans.url %}
        {% else %}
          {% set trans_url = SITEURL ~ '/' %}
        {% endif %}

      {% endfor %}

      {# Důležité: přidáme i odkaz na sebe sama (self-referencing), ale jen pokud existují jiné jazyky #}
      {# To pomáhá vyhledávačům pochopit, že tato stránka je hlavní verzí #}
      {% if page.translations %}

      {% endif %}


  {% endfor %}
